ALTER TABLE public.store_contacts ADD COLUMN IF NOT EXISTS verification_auto_send_link boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS verification_attempt_id uuid, ADD COLUMN IF NOT EXISTS verification_from_phone text, ADD COLUMN IF NOT EXISTS verification_method text, ADD COLUMN IF NOT EXISTS verification_override_reason text, ADD COLUMN IF NOT EXISTS verification_override_by uuid, ADD COLUMN IF NOT EXISTS verification_override_at timestamptz, ADD COLUMN IF NOT EXISTS last_call_outcome text, ADD COLUMN IF NOT EXISTS portal_link_attempt_at timestamptz, ADD COLUMN IF NOT EXISTS portal_link_status text, ADD COLUMN IF NOT EXISTS portal_link_error text, ADD COLUMN IF NOT EXISTS portal_link_invite_id uuid;
CREATE OR REPLACE FUNCTION public.contact_verification_can_access(p_store_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.store_master WHERE id=p_store_id AND deleted_at IS NULL) AND (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'admin') OR public.va_can_access_store(p_store_id) OR (public.is_internal_staff(auth.uid()) AND NOT public.has_role(auth.uid(),'va') AND NOT public.has_role(auth.uid(),'store')) OR (public.has_role(auth.uid(),'ambassador') AND public.ambassador_has_store_access(auth.uid(),p_store_id)) OR EXISTS(SELECT 1 FROM public.routes r JOIN public.route_stops s ON s.route_id=r.id WHERE s.store_id=p_store_id AND r.assigned_to=auth.uid() AND r.status NOT IN ('cancelled','canceled')) OR ((public.has_role(auth.uid(),'driver') OR public.has_role(auth.uid(),'biker')) AND public.user_has_store_access(p_store_id))) $$;
REVOKE ALL ON FUNCTION public.contact_verification_can_access(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.contact_verification_can_access(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.guard_contact_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF auth.uid() IS NOT NULL AND coalesce(auth.role(),'')<>'service_role' AND coalesce(current_setting('app.contact_verification_write',true),'')<>'on' THEN
IF TG_OP='INSERT' THEN IF coalesce(NEW.number_verification_status,'unverified')<>'unverified' OR NEW.number_verification_confirmed_at IS NOT NULL OR NEW.verification_method IS NOT NULL OR NEW.verification_attempt_id IS NOT NULL OR NEW.portal_link_attempt_at IS NOT NULL THEN RAISE EXCEPTION 'Use the contact verification flow'; END IF;
ELSIF ROW(NEW.number_verification_status,NEW.number_verification_confirmed_at,NEW.number_verification_sent_at,NEW.number_verification_delivered_at,NEW.number_verification_failed_at,NEW.number_verification_message_sid,NEW.number_verification_sent_by,NEW.number_verification_error,NEW.verification_method,NEW.verification_override_reason,NEW.verification_override_by,NEW.verification_override_at,NEW.verification_attempt_id,NEW.verification_from_phone,NEW.portal_link_attempt_at,NEW.portal_link_status,NEW.portal_link_error,NEW.portal_link_invite_id) IS DISTINCT FROM ROW(OLD.number_verification_status,OLD.number_verification_confirmed_at,OLD.number_verification_sent_at,OLD.number_verification_delivered_at,OLD.number_verification_failed_at,OLD.number_verification_message_sid,OLD.number_verification_sent_by,OLD.number_verification_error,OLD.verification_method,OLD.verification_override_reason,OLD.verification_override_by,OLD.verification_override_at,OLD.verification_attempt_id,OLD.verification_from_phone,OLD.portal_link_attempt_at,OLD.portal_link_status,OLD.portal_link_error,OLD.portal_link_invite_id) THEN RAISE EXCEPTION 'Use the contact verification flow'; END IF; END IF;
IF TG_OP='UPDATE' AND public.normalize_phone_e164(NEW.phone) IS DISTINCT FROM public.normalize_phone_e164(OLD.phone) THEN NEW.number_verification_status:='unverified'; NEW.number_verification_confirmed_at:=NULL; NEW.number_verification_sent_at:=NULL; NEW.number_verification_delivered_at:=NULL; NEW.number_verification_message_sid:=NULL; NEW.verification_method:=NULL; NEW.verification_attempt_id:=NULL; NEW.verification_from_phone:=NULL; NEW.verification_override_at:=NULL; NEW.verification_override_reason:=NULL; NEW.verification_override_by:=NULL; NEW.portal_link_attempt_at:=NULL; NEW.portal_link_status:=NULL; NEW.portal_link_error:=NULL; NEW.portal_link_invite_id:=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER contact_verification_guard BEFORE INSERT OR UPDATE ON public.store_contacts FOR EACH ROW EXECUTE FUNCTION public.guard_contact_verification();
CREATE OR REPLACE FUNCTION public.contact_verification_contacts(p_store_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.contact_verification_can_access(p_store_id) THEN RAISE EXCEPTION 'Not authorized for this store'; END IF; RETURN jsonb_build_object('contacts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'role',c.role,'phone',c.phone,'status',c.number_verification_status,'sent_at',c.number_verification_sent_at,'delivered_at',c.number_verification_delivered_at,'confirmed_at',c.number_verification_confirmed_at,'error',c.number_verification_error,'method',c.verification_method,'override_reason',c.verification_override_reason,'override_at',c.verification_override_at,'auto_send',c.verification_auto_send_link,'link_status',c.portal_link_status,'link_error',c.portal_link_error,'opted_out',c.opted_out,'last_call_outcome',c.last_call_outcome,'total_calls_attempted',c.total_calls_attempted,'total_calls_answered',c.total_calls_answered) ORDER BY c.is_primary DESC NULLS LAST,c.created_at),'[]'::jsonb) FROM public.store_contacts c WHERE c.store_id=p_store_id AND c.deleted_at IS NULL),'store_name',(SELECT store_name FROM public.store_master WHERE id=p_store_id),'portal_live',public.store_portal_is_live(),'is_test',(SELECT is_portal_test FROM public.store_master WHERE id=p_store_id),'can_override',public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'admin')); END $$;
REVOKE ALL ON FUNCTION public.contact_verification_contacts(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.contact_verification_contacts(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.contact_verification_save(p_store_id uuid,p_name text,p_role text,p_phone text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; n text:=public.normalize_phone_e164(p_phone); BEGIN IF NOT public.contact_verification_can_access(p_store_id) THEN RAISE EXCEPTION 'Not authorized for this store'; END IF; IF length(trim(coalesce(p_name,''))) NOT BETWEEN 1 AND 150 OR p_role NOT IN ('owner','manager','worker') OR n IS NULL OR n !~ '^\+[1-9][0-9]{7,14}$' THEN RAISE EXCEPTION 'Name, role and valid phone required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_store_id::text||right(regexp_replace(n,'\D','','g'),10),0)); SELECT id INTO c FROM public.store_contacts WHERE store_id=p_store_id AND right(regexp_replace(phone,'\D','','g'),10)=right(regexp_replace(n,'\D','','g'),10) ORDER BY deleted_at NULLS FIRST,created_at LIMIT 1; IF c IS NOT NULL THEN RETURN c; END IF; INSERT INTO public.store_contacts(store_id,name,role,phone,source,updated_by,is_simulation) VALUES(p_store_id,trim(p_name),p_role,n,'in_person_verification',auth.uid(),false) RETURNING id INTO c; RETURN c; END $$;
REVOKE ALL ON FUNCTION public.contact_verification_save(uuid,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.contact_verification_save(uuid,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.contact_verification_call_outcome(p_contact_id uuid,p_outcome text,p_attempt_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.store_contacts%ROWTYPE; BEGIN SELECT * INTO c FROM public.store_contacts WHERE id=p_contact_id AND deleted_at IS NULL FOR UPDATE; IF c.id IS NULL OR NOT public.contact_verification_can_access(c.store_id) THEN RAISE EXCEPTION 'Not authorized for this contact'; END IF; IF p_outcome NOT IN ('answered','no_answer','voicemail','wrong_number','disconnected') OR p_attempt_id IS NULL THEN RAISE EXCEPTION 'Invalid call outcome'; END IF; IF EXISTS(SELECT 1 FROM public.communication_logs WHERE idempotency_key='contact-call-'||p_attempt_id AND contact_id=c.id) THEN RETURN; END IF; INSERT INTO public.communication_logs(store_id,contact_id,channel,direction,outcome,summary,recipient_phone,created_by,business_id,idempotency_key) VALUES(c.store_id,c.id,'call','outbound',p_outcome,'At the store: contact verification call — '||p_outcome,c.phone,auth.uid(),(SELECT business_id FROM public.store_master WHERE id=c.store_id),'contact-call-'||p_attempt_id); UPDATE public.store_contacts SET last_call_outcome=p_outcome,updated_by=auth.uid() WHERE id=c.id; INSERT INTO public.store_notes(store_id,note_text,note_date,created_by,source) VALUES(c.store_id,'Contact verification: '||c.name||' ('||c.phone||'), call outcome: '||replace(p_outcome,'_',' ')||' at '||to_char(now(),'YYYY-MM-DD HH24:MI TZ'),current_date,auth.uid(),'in_person_verification'); END $$;
REVOKE ALL ON FUNCTION public.contact_verification_call_outcome(uuid,text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.contact_verification_call_outcome(uuid,text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.contact_verification_auto_link(p_contact_id uuid,p_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s uuid; BEGIN SELECT store_id INTO s FROM public.store_contacts WHERE id=p_contact_id AND deleted_at IS NULL; IF s IS NULL OR NOT public.contact_verification_can_access(s) THEN RAISE EXCEPTION 'Not authorized for this contact'; END IF; UPDATE public.store_contacts SET verification_auto_send_link=p_enabled,updated_by=auth.uid() WHERE id=p_contact_id; END $$;
REVOKE ALL ON FUNCTION public.contact_verification_auto_link(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.contact_verification_auto_link(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.contact_verification_override(p_contact_id uuid,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.store_contacts%ROWTYPE; BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Owner/admin only'; END IF; IF length(trim(coalesce(p_reason,''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'A reason of at least 5 characters is required'; END IF; SELECT * INTO c FROM public.store_contacts WHERE id=p_contact_id AND deleted_at IS NULL FOR UPDATE; IF c.id IS NULL THEN RAISE EXCEPTION 'Contact not found'; END IF; IF c.number_verification_status='confirmed' THEN RAISE EXCEPTION 'Already text verified'; END IF; PERFORM set_config('app.contact_verification_write','on',true); UPDATE public.store_contacts SET verification_method='in_person',verification_override_reason=trim(p_reason),verification_override_by=auth.uid(),verification_override_at=now(),updated_by=auth.uid() WHERE id=c.id; INSERT INTO public.store_notes(store_id,note_text,note_date,created_by,source) VALUES(c.store_id,'Verified in person — NOT text verified: '||c.name||'. Reason: '||trim(p_reason),current_date,auth.uid(),'in_person_verification'); PERFORM set_config('app.contact_verification_write','off',true); END $$;
REVOKE ALL ON FUNCTION public.contact_verification_override(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.contact_verification_override(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.contact_verification_begin(p_contact_id uuid,p_from text,p_auto boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.store_contacts%ROWTYPE; a uuid; BEGIN SELECT * INTO c FROM public.store_contacts WHERE id=p_contact_id AND deleted_at IS NULL FOR UPDATE; IF c.id IS NULL OR NOT public.contact_verification_can_access(c.store_id) THEN RAISE EXCEPTION 'Not authorized for this contact'; END IF; IF coalesce(c.opted_out,false) OR c.can_receive_sms=false THEN RAISE EXCEPTION 'Contact has opted out or SMS disabled'; END IF; IF c.number_verification_status='confirmed' THEN RAISE EXCEPTION 'Already confirmed'; END IF; IF c.number_verification_status IN ('sent','delivered') AND c.number_verification_sent_at>now()-interval '7 days' THEN RAISE EXCEPTION 'Verification already pending; wait for the reply'; END IF; IF EXISTS(SELECT 1 FROM public.dnc_list WHERE right(regexp_replace(phone_number,'\D','','g'),10)=right(regexp_replace(c.phone,'\D','','g'),10)) OR EXISTS(SELECT 1 FROM public.opt_out_events WHERE right(regexp_replace(phone_number,'\D','','g'),10)=right(regexp_replace(c.phone,'\D','','g'),10)) THEN RAISE EXCEPTION 'Number suppressed; YES does not lift STOP'; END IF; IF public.normalize_phone_e164(c.phone) IS NULL OR public.normalize_phone_e164(p_from) IS NULL THEN RAISE EXCEPTION 'Invalid verification phone'; END IF; a:=gen_random_uuid(); PERFORM set_config('app.contact_verification_write','on',true); UPDATE public.store_contacts SET verification_attempt_id=a,verification_from_phone=public.normalize_phone_e164(p_from),verification_auto_send_link=p_auto,verification_method=NULL,number_verification_status='sent',number_verification_sent_at=now(),number_verification_sent_by=auth.uid(),number_verification_message_sid=NULL,number_verification_delivered_at=NULL,number_verification_confirmed_at=NULL,number_verification_failed_at=NULL,number_verification_error=NULL,portal_link_attempt_at=NULL,portal_link_status=NULL,portal_link_error=NULL,portal_link_invite_id=NULL WHERE id=c.id; PERFORM set_config('app.contact_verification_write','off',true); RETURN jsonb_build_object('attempt_id',a,'contact_id',c.id,'phone',public.normalize_phone_e164(c.phone),'store_id',c.store_id,'name',c.name,'store_name',(SELECT store_name FROM public.store_master WHERE id=c.store_id),'business_id',(SELECT business_id FROM public.store_master WHERE id=c.store_id)); END $$;
REVOKE ALL ON FUNCTION public.contact_verification_begin(uuid,text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.contact_verification_begin(uuid,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.contact_verification_receive(p_from text,p_to text,p_body text,p_sid text,p_business_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.store_contacts%ROWTYPE; ids uuid[]; d text:=right(regexp_replace(p_from,'\D','','g'),10); BEGIN IF lower(trim(p_body)) NOT IN ('yes','y','yeah','ok','confirmed') OR length(d)<>10 OR p_business_id IS NULL THEN RETURN jsonb_build_object('matched',false); END IF; SELECT array_agg(sc.id) INTO ids FROM public.store_contacts sc JOIN public.store_master sm ON sm.id=sc.store_id WHERE sc.deleted_at IS NULL AND sm.deleted_at IS NULL AND sm.business_id=p_business_id AND right(regexp_replace(sc.phone,'\D','','g'),10)=d AND sc.number_verification_status IN ('sent','delivered') AND sc.number_verification_sent_at>=now()-interval '7 days' AND public.normalize_phone_e164(sc.verification_from_phone)=public.normalize_phone_e164(p_to) AND sc.verification_attempt_id IS NOT NULL; IF coalesce(array_length(ids,1),0)<>1 THEN RETURN jsonb_build_object('matched',false,'ambiguous',coalesce(array_length(ids,1),0)>1); END IF; SELECT * INTO c FROM public.store_contacts WHERE id=ids[1] FOR UPDATE; IF c.number_verification_status NOT IN ('sent','delivered') THEN RETURN jsonb_build_object('matched',false); END IF; IF coalesce(c.opted_out,false) OR EXISTS(SELECT 1 FROM public.dnc_list WHERE right(regexp_replace(phone_number,'\D','','g'),10)=d) OR EXISTS(SELECT 1 FROM public.opt_out_events WHERE right(regexp_replace(phone_number,'\D','','g'),10)=d) THEN UPDATE public.store_contacts SET number_verification_status='failed',number_verification_error='Suppressed: YES does not lift STOP',number_verification_failed_at=now() WHERE id=c.id; RETURN jsonb_build_object('matched',true,'confirmed',false,'blocked',true); END IF; UPDATE public.store_contacts SET number_verification_status='confirmed',number_verification_confirmed_at=now(),verification_method='text_reply',verification_override_reason=NULL,verification_override_by=NULL,verification_override_at=NULL,responsive_by_text=true,last_text_received_at=now(),sms_opt_in_status='opted_in',sms_opt_in_source='in_person_verification',sms_opt_in_at=now(),can_receive_sms=true,portal_link_status=CASE WHEN verification_auto_send_link THEN 'ready' ELSE NULL END WHERE id=c.id; UPDATE public.store_master SET phone_verified_at=greatest(coalesce(phone_verified_at,'-infinity'::timestamptz),now()) WHERE id=c.store_id; INSERT INTO public.communication_logs(store_id,contact_id,channel,direction,summary,message_content,sender_phone,recipient_phone,twilio_sid,business_id,delivery_status,outcome,idempotency_key) VALUES(c.store_id,c.id,'sms','inbound','Contact verification: Replied YES',trim(p_body),p_from,p_to,p_sid,p_business_id,'received','verification_confirmed','contact-yes-'||c.verification_attempt_id); INSERT INTO public.store_notes(store_id,note_text,note_date,created_by,source) VALUES(c.store_id,'Contact text verified: '||c.name||' ('||c.phone||') replied '||upper(trim(p_body))||' at '||to_char(now(),'YYYY-MM-DD HH24:MI TZ'),current_date,c.number_verification_sent_by,'in_person_verification'); RETURN jsonb_build_object('matched',true,'confirmed',true,'contact_id',c.id,'store_id',c.store_id,'auto_send',c.verification_auto_send_link); END $$;
REVOKE ALL ON FUNCTION public.contact_verification_receive(text,text,text,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.contact_verification_receive(text,text,text,text,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.contact_verification_claim_link(p_store_id uuid,p_contact_id uuid,p_actor uuid,p_auto boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.store_contacts%ROWTYPE; s public.store_master%ROWTYPE; d text; BEGIN SELECT * INTO c FROM public.store_contacts WHERE id=p_contact_id AND store_id=p_store_id AND deleted_at IS NULL FOR UPDATE; IF c.id IS NULL OR c.number_verification_status<>'confirmed' OR c.number_verification_confirmed_at IS NULL OR c.verification_method='in_person' THEN RAISE EXCEPTION 'Number must be confirmed by text before sending an app link'; END IF; SELECT * INTO s FROM public.store_master WHERE id=p_store_id AND deleted_at IS NULL; IF s.id IS NULL THEN RAISE EXCEPTION 'Store not found'; END IF; d:=right(regexp_replace(c.phone,'\D','','g'),10); IF coalesce(c.opted_out,false) OR c.can_receive_sms=false OR EXISTS(SELECT 1 FROM public.dnc_list WHERE right(regexp_replace(phone_number,'\D','','g'),10)=d) OR EXISTS(SELECT 1 FROM public.opt_out_events WHERE right(regexp_replace(phone_number,'\D','','g'),10)=d) THEN RAISE EXCEPTION 'Number has opted out'; END IF; IF p_auto AND NOT c.verification_auto_send_link THEN RETURN jsonb_build_object('status','auto_off'); END IF; IF NOT public.store_portal_is_live() AND NOT coalesce(s.is_portal_test,false) THEN UPDATE public.store_contacts SET portal_link_status='ready_locked',portal_link_error='Portal not live yet' WHERE id=c.id; RETURN jsonb_build_object('status','ready_locked'); END IF; IF c.portal_link_attempt_at IS NOT NULL THEN RETURN jsonb_build_object('status',coalesce(c.portal_link_status,'sending'),'already_attempted',true,'error',c.portal_link_error); END IF; UPDATE public.store_contacts SET portal_link_attempt_at=now(),portal_link_status='sending',portal_link_error=NULL WHERE id=c.id; RETURN jsonb_build_object('status','claimed','contact_id',c.id,'phone',public.normalize_phone_e164(c.phone),'name',c.name,'store_id',s.id,'store_name',s.store_name,'business_id',s.business_id,'actor',coalesce(p_actor,c.number_verification_sent_by),'attempt_id',coalesce(c.verification_attempt_id,c.id)); END $$;
REVOKE ALL ON FUNCTION public.contact_verification_claim_link(uuid,uuid,uuid,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.contact_verification_claim_link(uuid,uuid,uuid,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.handle_sms_opt_out(p_phone text,p_method text DEFAULT 'STOP_keyword') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n text:=public.normalize_phone_e164(p_phone); d text; c uuid; BEGIN IF n IS NULL THEN RAISE EXCEPTION 'Unparseable phone'; END IF; d:=right(regexp_replace(n,'\D','','g'),10); INSERT INTO public.opt_out_events(phone_number,source,reason) VALUES(n,'sms_inbound',p_method) ON CONFLICT(phone_number) DO UPDATE SET source=excluded.source,reason=excluded.reason,created_at=now(); INSERT INTO public.dnc_list(phone_number,phone_e164,source,reason) VALUES(n,n,'sms_inbound',p_method) ON CONFLICT(phone_number) DO UPDATE SET phone_e164=excluded.phone_e164,source=excluded.source,reason=excluded.reason; UPDATE public.store_contacts SET opted_out=true,opted_out_at=now(),opted_out_method=p_method,sms_opt_in_status='opted_out',number_verification_status=CASE WHEN number_verification_status IN ('sent','delivered') THEN 'failed' ELSE number_verification_status END,number_verification_error='STOP received; no more texts',portal_link_status='blocked',portal_link_error='STOP received' WHERE right(regexp_replace(phone,'\D','','g'),10)=d; SELECT id INTO c FROM public.store_contacts WHERE right(regexp_replace(phone,'\D','','g'),10)=d ORDER BY created_at LIMIT 1; RETURN c; END $$;
REVOKE ALL ON FUNCTION public.handle_sms_opt_out(text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.handle_sms_opt_out(text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.store_portal_onboarding_counts() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'owner') OR public.has_role(auth.uid(),'admin') OR public.is_staff(auth.uid())) THEN RAISE EXCEPTION 'Staff only'; END IF; RETURN jsonb_build_object('contacts_verified_this_week',(SELECT count(*) FROM public.store_contacts c JOIN public.store_master s ON s.id=c.store_id WHERE c.deleted_at IS NULL AND s.deleted_at IS NULL AND NOT coalesce(s.is_portal_test,false) AND c.number_verification_status='confirmed' AND c.number_verification_confirmed_at>=date_trunc('week',now())),'stores_invited',(SELECT count(DISTINCT c.store_id) FROM public.communication_logs c JOIN public.store_master s ON s.id=c.store_id WHERE c.source_table='portal_invites' AND c.direction='outbound' AND c.delivery_status IN ('sent','accepted','queued','delivered') AND c.error_code IS NULL AND s.deleted_at IS NULL AND NOT coalesce(s.is_portal_test,false)),'stores_signed_in',(SELECT count(DISTINCT su.store_id) FROM public.store_users su JOIN public.store_master s ON s.id=su.store_id JOIN auth.users u ON u.id=su.user_id WHERE u.last_sign_in_at IS NOT NULL AND s.deleted_at IS NULL AND NOT coalesce(s.is_portal_test,false))); END $$;
REVOKE ALL ON FUNCTION public.store_portal_onboarding_counts() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.store_portal_onboarding_counts() TO authenticated;